from mcp.server.fastmcp import Context, FastMCP

mcp = FastMCP("work-graph")


@mcp.tool()
def list_tasks(query: str, ctx: Context) -> list:
    """Search tasks in the caller's own workspace."""
    workspace_id = ctx.session.claims["workspace_id"]
    return db.search_tasks(workspace_id, query)
